thread_local int counter = 0;
void foo() { ++counter; }
int main() {
  std::array<int, 3> result{};
  std::array<std::thread, 3> ts;
  for (int i = 0; i < 3; ++i)
    ts[i] = std::thread([i, &result] {
      for (int k = 0; k < 100; ++k) foo();
      result[i] = counter; });
  for (auto& t : ts) t.join();
  std::cout << result[0] << ' ' << result[1]
    << ' ' << result[2] << '\n' << counter;
}

