// GCC / libstdc++ on Linux
// Called for every incoming message
void on_message(const Msg& m) {
  pending.push_back(std::async(
      std::launch::async,
      [m] { handle(m); }));
}

SpscRing<Msg, 4096> ring;  // preallocated
void on_message(const Msg& m) {
  if (!ring.try_push(m)) on_overflow(m);
}
void worker() {  // pinned, isolated core
  for (Msg m;;)
    if (ring.try_pop(m)) handle(m);
}

std::atomic<bool> initialized{false};

// called by many threads
void get_config() {
  if (!initialized) {
    init();            // loads config
    initialized = true;
  }
  use_config();
}

std::once_flag once;

void get_config() {
  std::call_once(once, init);
  use_config();
}
